CustomField.formula:
if (contains(Participant_Name__c, "CBOC"), "CBOC", 

if (contains(Notes__c, "not counted"), "Not Counted", 

if (Counted_as_Job_Only__c = TRUE, "Counted as Job Only", 

if (isblank (Placement_Number__c), NULL, 

if (TEXT( Job_Type__c ) = "Short-Term" , NULL, 

if (value(right(text(Placement_Year__c), 2)) < 17, "See 'One-Year Retention Category, FY14-FY17'",

if (ispickval (Job_Type__c, "Permanent-Advancement"), text(Job_Type__c), 

if (ispickval (Retention_Exception__c, "Retention Override") || ispickval (Retention_Exception__c, "Retention Tracked Under Previous Placement"), text (Retention_Exception__c), 

if (Retention_Days_Lapsed_Since_Start_FY18__c >= 365, "#Retained One Year", 

if (isblank (One_Year_Retention_End_Date__c), "Tracking", 

if (ispickval (Job_Type__c, "External Transitional") && One_Year_Retention_End_Date__c >= ETJ_Commitment_End_Date__c && not (ispickval (End_Type__c, "Terminated")), "#Retained ETJ",

"Lost Employment")))))))))))
